import * as THREE from '../vendor/three.module.min.js';
import {OrbitControls} from '../vendor/OrbitControls.js';
import {SOCKET_POSITIONS,terrainMesh,terrainHeight} from './physics.mjs';
const colors={rubber:0x35465a,metal:0x91b7c6,fuel:0xf6bc41};
export class WorkshopView {
 constructor(host,onBlock){this.host=host;this.onBlock=onBlock;this.scene=new THREE.Scene();this.scene.background=new THREE.Color('#d8eced');this.camera=new THREE.PerspectiveCamera(45,1,.1,240);this.camera.position.set(8,7,10);this.renderer=new THREE.WebGLRenderer({antialias:true});this.renderer.setPixelRatio(Math.min(devicePixelRatio||1,2));host.append(this.renderer.domElement);this.renderer.domElement.addEventListener("webglcontextlost",e=>{e.preventDefault();dispatchEvent(new Event("msv-workshop-render-failed"));});this.controls=new OrbitControls(this.camera,this.renderer.domElement);this.controls.target.set(0,1,0);this.controls.enableDamping=true;this.controls.minDistance=3;this.controls.maxDistance=65;
  this.scene.add(new THREE.HemisphereLight(0xffffff,0x657f65,2.5));const sun=new THREE.DirectionalLight(0xffffff,2);sun.position.set(4,12,6);this.scene.add(sun);
  this.grid=new THREE.GridHelper(10,10,0x345861,0x7b9a97);this.scene.add(this.grid);this.blocks=new THREE.Group();this.car=new THREE.Group();this.land=new THREE.Group();this.scene.add(this.blocks,this.car,this.land);this.makeTerrain();this.ray=new THREE.Raycaster();this.pointer=new THREE.Vector2();this.editorMode='camera';this.currentMode='build';this.follow=false;this.lastTarget=null;
  this.renderer.domElement.addEventListener('pointerdown',e=>{this.down=[e.clientX,e.clientY];});this.renderer.domElement.addEventListener('pointerup',e=>{if(!this.down||Math.hypot(e.clientX-this.down[0],e.clientY-this.down[1])>6||this.editorMode==='camera'||this.currentMode!=='build')return;const rect=this.renderer.domElement.getBoundingClientRect();this.pointer.set((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1);this.ray.setFromCamera(this.pointer,this.camera);const hit=this.ray.intersectObjects(this.blocks.children)[0];let c;if(hit){c={...hit.object.userData.block};if(this.editorMode==='place'){const normal=hit.face.normal;c.x+=Math.round(normal.x);c.y+=Math.round(normal.y);c.z+=Math.round(normal.z);}}else{const p=new THREE.Vector3();if(this.ray.ray.intersectPlane(new THREE.Plane(new THREE.Vector3(0,1,0),0),p))c={x:Math.round(p.x),y:0,z:Math.round(p.z)};}if(c)this.onBlock(c);});
  this.resize=new ResizeObserver(()=>{const {width,height}=host.getBoundingClientRect();if(width&&height){this.renderer.setSize(width,height,false);this.camera.aspect=width/height;this.camera.updateProjectionMatrix();}});this.resize.observe(host);
 }
 highlight(cube){cube.add(new THREE.LineSegments(new THREE.EdgesGeometry(cube.geometry),new THREE.LineBasicMaterial({color:0xf4c84b})));}
 box(size,color){return new THREE.Mesh(new THREE.BoxGeometry(...size),new THREE.MeshStandardMaterial({color,roughness:.8}));}
 clear(group){for(const child of [...group.children]){child.traverse(n=>{n.geometry?.dispose();if(n.material)n.material.dispose();});group.remove(child);}}
 makeTerrain(){const {vertices,indices}=terrainMesh(),geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.BufferAttribute(vertices,3));geometry.setIndex(new THREE.BufferAttribute(indices,1));geometry.computeVertexNormals();const mesh=new THREE.Mesh(geometry,new THREE.MeshStandardMaterial({color:0x7cba64,roughness:1,side:THREE.DoubleSide}));this.land.add(mesh);
  // Original voxel scenery: no Minecraft textures, trademarks or external assets.
  for(let x=-8;x<=48;x+=2){for(const z of [-6.7,6.7]){const h=terrainHeight(x),soil=this.box([1.96,2,1],0x967550);soil.position.set(x,h-1,z);this.land.add(soil);const grass=this.box([1.96,.16,1],0x75a855);grass.position.set(x,h-.02,z);this.land.add(grass);}}
  for(const x of [-5,8,19,33,45]){const h=terrainHeight(x),z=-6.5,trunk=this.box([.45,1.8,.45],0x886443);trunk.position.set(x,h+.9,z);this.land.add(trunk);const leaves=this.box([1.6,1.5,1.6],0x438856);leaves.position.set(x,h+2.3,z);this.land.add(leaves);}
  for(const [x,labelColor]of [[6,0xf3cf57],[14,0x4080d8],[26,0xef7657],[35,0x53a68d]]){const marker=this.box([.15,3,.15],labelColor);marker.position.set(x,1.2,-5);this.land.add(marker);}this.land.visible=false;}
 editMode(mode){this.editorMode=mode;this.controls.enabled=mode==='camera'||this.currentMode!=='build';}
 setProject(project,mode,selectedBlocks=new Set(),selectedInstance=''){this.project=project;this.currentMode=mode;this.blocks.visible=mode==='build';this.car.visible=mode!=='build';this.grid.visible=mode==='build';this.land.visible=mode!=='build';this.controls.enabled=this.editorMode==='camera'||mode!=='build';this.clear(this.blocks);this.clear(this.car);this.instanceGroups=new Map();
  for(const b of project.blocks){const cube=this.box([.94,.94,.94],colors[b.material]);if(selectedBlocks.has(`${b.x},${b.y},${b.z}`))this.highlight(cube);cube.position.set(b.x,b.y+.5,b.z);cube.userData.block=b;this.blocks.add(cube);}
  const chassis=this.box([3,.4,1.2],0x2c609a);this.chassis=new THREE.Group();this.chassis.add(chassis);this.car.add(this.chassis);this.chassis.position.y=.95;
  for(const [socket,position]of Object.entries(SOCKET_POSITIONS)){const marker=this.box([.14,.14,.14],0xf1ce59);marker.position.fromArray(position);this.chassis.add(marker);marker.userData.socket=socket;}
  for(const i of project.instances){const d=project.definitions.find(d=>d.id===i.definitionId),g=new THREE.Group();const min={},max={};for(const axis of ['x','y','z']){min[axis]=Math.min(...d.blocks.map(b=>b[axis]));max[axis]=Math.max(...d.blocks.map(b=>b[axis]));}for(const b of d.blocks){const cube=this.box([.38,.38,.38],colors[b.material]);if(i.id===selectedInstance)this.highlight(cube);cube.position.set((b.x-(min.x+max.x)/2)*.4,(b.y-(min.y+max.y)/2)*.4,(b.z-(min.z+max.z)/2)*.4);g.add(cube);}g.userData.instance=i;this.instanceGroups.set(i.id,g);if(i.socket==='engine'){this.chassis.add(g);g.position.fromArray(SOCKET_POSITIONS.engine);g.rotation.y=i.rotation*Math.PI/180;const arrow=new THREE.ArrowHelper(new THREE.Vector3(i.rotation===180?-1:1,0,0),new THREE.Vector3(-1.15,.5,0),1.6,0xef7657,.3,.2);this.chassis.add(arrow);}else{this.car.add(g);g.position.fromArray(SOCKET_POSITIONS[i.socket]);g.position.y+=.95;}}
 }
 pose(snapshot){if(!snapshot)return;this.chassis.position.copy(snapshot.chassis.p);this.chassis.quaternion.copy(snapshot.chassis.q);for(const w of snapshot.wheels){const g=this.instanceGroups.get(w.id);if(g){g.position.copy(w.p);g.quaternion.copy(w.q);}}if(this.follow){const target=new THREE.Vector3().copy(snapshot.chassis.p);if(this.lastTarget)this.camera.position.add(target.clone().sub(this.lastTarget));this.controls.target.copy(target);this.lastTarget=target;}}
 home(){const target=this.currentMode==='build'?new THREE.Vector3(0,1,0):this.chassis.position.clone();this.camera.position.copy(target).add(new THREE.Vector3(6,4.5,7));this.controls.target.copy(target);this.lastTarget=target;this.controls.update();}
 render(){this.controls.update();this.renderer.render(this.scene,this.camera);}
}
